exercises.solution:
def parser_quantite(texte):
    try:
        quantite = int(texte)
    except ValueError:
        raise ValueError("texte illisible")
    if quantite < 0:
        raise ValueError("quantité négative")
    return quantite


def bilan_ventes(lignes):
    total = 0
    acceptes = []
    erreurs = []
    for numero, ligne in enumerate(lignes, start=1):
        try:
            quantite = parser_quantite(ligne["quantite"])
        except ValueError as erreur:
            erreurs.append({"ligne": numero, "message": str(erreur)})
        else:
            total += quantite * ligne["prix"]
            acceptes.append(ligne["nom"])
    return {"total": total, "acceptes": acceptes, "erreurs": erreurs}

